/* Route renderers. Business calculations live in core.js; actions live in app.js. */
(function(){'use strict';const T=window.TF,C=T.C,I=T.icon,E=T.escape;const P=T.P={};
const actions=()=>C.btn('Export','export','download')+C.btn('Create task','task-new','plus','primary');
const companyNotice=()=>C.notice('Showing <b>'+E(T.org().name)+'</b> only. Private personal work never enters company metrics.');
P.dashboard=()=>{let mine=T.tasks('mine'),m=T.metrics(mine),tab=T.ui.tabs.dashboard||'today',due=mine.filter(t=>t.due===T.today()&&!T.isTerminal(t)),next=mine.filter(t=>t.due>T.today()&&!T.isTerminal(t)).sort((a,b)=>a.due.localeCompare(b.due)),done=mine.filter(t=>t.status==='Done'),shown=tab==='today'?due:tab==='upcoming'?next:tab==='completed'?done:mine,blocked=T.tasks().filter(t=>t.status==='Blocked'),projects=T.projects().slice(0,3);return C.heading('A little clarity. A lot of possibility.',`${new Date(T.today()+'T12:00:00').toLocaleDateString('en',{weekday:'long'})} focus, ${E(T.me().name.split(' ')[0])}. Let’s make space for what matters.`,`<span class="row date-button">${I('calendar','sm')}${T.date(T.today(),{weekday:'short',year:'numeric'})}</span>`+C.btn('Create task','task-new','plus','primary'))+`<section class="welcome-banner"><div><div class="eyebrow">YOUR WORK, BEAUTIFULLY IN SYNC</div><h2>Big plans. Thoughtful progress.</h2><p>You have ${due.length} priorities due today. One clear next step at a time.</p></div><div class="banner-stat"><b style="font-size:22px;font-weight:500">${m.rate}%</b><br>of your tasks completed</div>${C.art()}</section><div class="metrics">${C.metric('My open tasks',m.open,'Across your company & private work','checkSquare','',{status:'open'})}${C.metric('Due today',due.length,'Keep your next steps in focus','calendar','orange',{status:'today'})}${C.metric('Completed tasks',m.done,`<span class="trend">${m.rate}%</span> overall completion`,'checkSquare','green',{status:'Done'})}${C.metric('Active projects',new Set(mine.map(t=>t.project)).size,'A shared view of your commitments','folder','blue',{type:'myprojects'})}</div><div class="dashboard-grid"><div><section class="card"><div class="card-head"><h2>Your priorities</h2>${C.link('View all tasks '+I('arrowUp','sm'),'nav',{id:'work'})}</div>${C.tabs([['today','Today',due.length],['upcoming','Upcoming',next.length],['all','All work',mine.length],['completed','Completed',done.length]],tab,'dashboard-tab')}<div id="priority-table">${C.taskTable(shown.slice(0,5),{compact:true})}</div><div class="task-footer"><span>${shown.length?`Showing ${Math.min(5,shown.length)} of ${shown.length} tasks`:'Everything is up to date'}</span>${C.link('+ Add a task','task-new')}</div></section><div class="chart-row">${C.card('A week of steady progress',C.lineChart(mine),C.badge('Your work','gray'),'','Completions and task deadlines from demo records')}${C.card('Work at a glance',C.donut(mine))}</div>${C.card('The latest around you',C.activity(T.db.activity.filter(a=>a.org===T.activeOrg()||a.org==='personal')),C.link('Activity log '+I('arrowUp','sm'),'audit-open'))}</div><div class="dashboard-right"><section class="card intelligence-card"><div class="card-head"><h2 class="row">${I('sparkles','sm')} A clearer perspective</h2>${C.badge('Demo AI','gray')}</div><p class="intelligence-intro">A little context for a more considered day.</p><div class="insight-item"><span class="insight-symbol">${I('target')}</span><div><h3>${blocked.length} dependencies need attention</h3><p>${blocked.length?'Review blocked work before the next milestone. A quick conversation could keep delivery moving.':'Your company has no blocked tasks. Keep reviewing upcoming deadlines.'}</p></div></div><div class="insight-item"><span class="insight-symbol">${I('clock')}</span><div><h3>Make a little room for focus</h3><p>${due.length} priorities land today. Start with your highest-impact work and protect time to finish.</p></div></div>${C.btn('Explore your intelligence center '+I('arrowUp','sm'),'nav','','',{id:'ai'})}<div class="tiny muted" style="margin-top:12px;font-size:8px">Rules-based demo · No live model connected</div></section>${C.card('Project pulse',C.projectPulse(projects),C.link('View all '+I('arrowUp','sm'),'nav',{id:'projects'}))}${C.card('Coming into view',next.slice(0,3).map(t=>`<div class="meeting"><div class="meeting-time">${T.date(t.due)}</div><div class="meeting-content"><button class="task-title" style="font-size:10px" data-action="task-open" data-id="${t.id}">${E(t.title)}</button><p>${E(T.project(t.project).department)}</p></div></div>`).join('')||'<p>No upcoming deadlines.</p>',C.link('Calendar '+I('arrowUp','sm'),'nav',{id:'calendar'}))}</div></div>`};
P.work=()=>{let view=T.ui.tabs.work||'all',scope=view==='team'?'all':'mine',ts=T.filteredTasks(scope);if(view==='today')ts=ts.filter(t=>t.due===T.today());if(view==='overdue')ts=ts.filter(T.overdue);if(view==='done')ts=ts.filter(t=>t.status==='Done');T.ui.currentTasks=ts;return C.heading('My work','One thoughtful list for everything you’re moving forward.',actions())+C.tabs([['all','Assigned to me',T.tasks('mine').length],['today','Due today'],['overdue','Overdue'],['done','Completed'],['team','Authorized team work']],view,'work-tab')+C.filterBar()+((T.ui.filters.work?.onlyOpen||T.ui.filters.work?.attention)?C.notice('Focused view: '+(T.ui.filters.work.onlyOpen?'open work':'blocked or overdue work')+' '+C.link('Clear focused filter','filters-clear'),'purple'):'')+`<div id="bulk-bar">${T.ui.selected.size?`<div class="notice purple row"><b>${T.ui.selected.size} selected</b><span class="spacer"></span>${C.btn('Mark done','bulk-done','check','soft')}${C.btn('Clear','selection-clear')}</div>`:''}</div><section class="card" id="work-table">${C.taskTable(ts,{select:true})}</section><div class="task-footer"><span>${ts.length} task${ts.length===1?'':'s'} · ${T.activeOrg()==='personal'?'Personal workspace':E(T.org().name)} + your private work</span><span>Cancelled tasks are excluded from completion metrics</span></div>`};
P.projects=personal=>{let mode=personal?'personal':'company',f=T.ui.filters.projects||{},ps=(f.archive?T.db.projects.filter(p=>p.archived&&T.visibleProject(p)&&(personal?p.org==='personal':p.org===T.activeOrg())):T.projects(mode)).filter(p=>(!f.query||p.name.toLowerCase().includes(f.query.toLowerCase()))&&(!f.health||f.health==='All health'||T.health(p)===f.health)),view=T.ui.tabs.projects||'grid';return C.heading(personal?'A space that’s just yours.':'Projects, moving together.',personal?'Personal goals and projects, kept separate from enterprise work.':'The big picture, the details, and the people bringing it to life.',C.btn('New project','project-new','plus','primary',{scope:mode}))+(personal?C.notice('Your private workspace · Only your personal projects appear here.','purple','lock'):'')+`<div class="toolbar"><div class="filter-group"><div class="filter-search">${I('search')}<input placeholder="Find a project…" aria-label="Find a project" data-input="project-search" value="${E(f.query||'')}"></div><select aria-label="Project health" data-change="project-health">${['All health','On track','Needs attention','At risk'].map(s=>`<option ${f.health===s?'selected':''}>${s}</option>`).join('')}</select></div>${C.btn(f.archive?'Show active':'Show archived','projects-archive-view','folder','')}<div class="segmented"><button class="${view==='grid'?'active':''}" data-action="projects-view" data-id="grid">${I('dashboard')} Grid</button><button class="${view==='list'?'active':''}" data-action="projects-view" data-id="list">${I('list')} List</button></div></div><div id="projects-results">${view==='grid'?`<div class="grid3">${ps.map(C.projectCard).join('')}<button class="card new-project-card" data-action="project-new" data-scope="${mode}">${I('plus')}<h3>Bring a new idea to life</h3><p>Create a ${personal?'private':'company'} project</p></button></div>`:C.card('Project directory',`<div class="table-wrap"><table><thead><tr><th>Project</th><th>Owner</th><th>Health</th><th>Progress</th><th>Target</th></tr></thead><tbody>${ps.map(p=>`<tr><td><div class="row">${C.projectIcon(p)}<button class="task-title" data-action="project-open" data-id="${p.id}">${E(p.name)}</button></div></td><td>${C.avatar(p.owner)}</td><td>${C.badge(T.health(p))}</td><td style="min-width:120px">${C.progress(T.progress(p),p.color)}<p class="tiny muted" style="margin-top:5px">${T.progress(p)}%</p></td><td>${T.date(p.due)}</td></tr>`).join('')}</tbody></table></div>`)}</div>`};
P.project=id=>{let p=T.project(id);if(!p||!T.visibleProject(p))return P.denied();let ts=T.projectTasks(id),m=T.metrics(ts),tab=T.ui.projectTab||'overview';let body='';if(tab==='overview')body=`<div class="dashboard-grid"><div>${C.card('A shared direction',`<p>${E(p.description)}</p><div class="grid2" style="margin-top:20px"><div><div class="tiny muted">ACCOUNTABLE OWNER</div><div class="row" style="margin-top:10px">${C.avatar(p.owner)}<h3>${E(T.user(p.owner).name)}</h3></div></div><div><div class="tiny muted">PROJECT TEAM</div><div style="margin-top:10px">${C.avatars(p.members)}</div></div></div>`)}${C.card('Milestones that matter',p.milestones.map(m=>`<div class="milestone"><input type="checkbox" data-change="milestone" data-project="${p.id}" data-id="${m.id}" aria-label="Complete ${E(m.title)}" ${m.done?'checked':''} ${!T.canEdit()?'disabled':''}><span class="milestone-title ${m.done?'done-title':''}">${E(m.title)}</span><span class="spacer"></span><span class="tiny muted">${T.date(m.due)}</span></div>`).join(''),C.link('+ Add milestone','milestone-new',{id:p.id}))}${C.card('Recent project activity',C.activity(T.db.activity.filter(a=>a.project===p.id)))}</div><div>${C.card('Project health',C.badge(T.health(p))+`<p style="margin-top:15px">${m.blocked?m.blocked+' blocked tasks require a dependency review.':m.overdue?m.overdue+' overdue tasks require a timeline review.':'No blocked or overdue tasks in this project.'}</p><div style="margin:20px 0 8px">${C.progress(m.rate,p.color)}</div><p class="tiny">${m.done} of ${m.total} eligible tasks complete · ${m.rate}%</p>`)}${C.card('Upcoming work',C.taskTable(ts.filter(t=>!T.isTerminal(t)).slice(0,4),{compact:true}))}</div></div>`;if(tab==='tasks')body=C.card('Project task register',C.taskTable(ts),C.btn('Create task','task-new','plus','soft',{project:p.id}));if(tab==='board')body=C.board(ts,p.id);if(tab==='timeline')body=C.card('Delivery timeline',C.timeline(ts),'','','Task start dates and deadlines from the project register');if(tab==='files')body=C.card('Project files',C.notice('Files stay in this browser. Uploads are limited to 1 MB each; no cloud storage is connected.')+C.files(p.files,'project',p.id),C.btn('Upload file','file-upload','upload','soft',{kind:'project',id:p.id}));if(tab==='activity')body=C.card('Project activity',C.activity(T.db.activity.filter(a=>a.project===p.id)));return `<div style="margin-bottom:17px">${C.link(I('left','sm')+' Back to '+(p.org==='personal'?'personal projects':'projects'),'nav',{id:p.org==='personal'?'personal':'projects'})}</div><div class="page-heading"><div class="project-heading">${C.projectIcon(p)}<div><h1>${E(p.name)}</h1><p>${E(p.department)} · ${p.org==='personal'?'Private workspace':E(T.org().name)} · Due ${T.date(p.due)}</p></div></div><div class="row actions">${C.btn('Edit project','project-edit','pen','',{id:p.id})}${C.btn('Add task','task-new','plus','primary',{project:p.id})}</div></div><div class="metrics">${C.metric('Eligible tasks',m.total,'Cancelled work excluded','checkSquare')}${C.metric('Completion',m.rate+'%',m.done+' completed tasks','target','green')}${C.metric('Needs attention',m.attention,'Unique blocked + overdue tasks','warning','orange')}${C.metric('Remaining effort',m.hours+'h','Estimates for all open tasks','clock','blue')}</div>${C.tabs(['overview','tasks','board','timeline','files','activity'].map(x=>[x,x[0].toUpperCase()+x.slice(1)]),tab,'project-tab',{project:p.id})}${body}`};
C.files=(files,kind,id)=>files.length?files.map(f=>`<div class="file-item"><span class="file-symbol">${I('file')}</span><div><h3>${E(f.name)}</h3><p class="tiny muted">${(f.size/1024).toFixed(1)} KB · ${T.date(f.date)}</p></div><span class="spacer"></span>${C.iconbtn('Download '+f.name,'file-download','download',{kind,id,file:f.id})}${C.iconbtn('Remove '+f.name,'file-remove','trash',{kind,id,file:f.id})}</div>`).join(''):C.empty('A place for your project context','Upload a brief, checklist, or other supporting file.');
P.board=()=>{let ps=T.projects('all'),p=T.ui.boardProject,ts=T.tasks('all').filter(t=>p==='all'||t.project===p);return C.heading('A clearer flow of work.','See the next step. Surface dependencies. Keep your team in sync.',C.btn('Create task','task-new','plus','primary'))+`<div class="toolbar"><div class="filter-group"><select aria-label="Board project" data-change="board-project"><option value="all">All authorized projects</option>${ps.map(p=>`<option value="${p.id}" ${T.ui.boardProject===p.id?'selected':''}>${E(p.name)}${p.org==='personal'?' · Private':''}</option>`).join('')}</select><span class="pill">${I('users','sm')} ${T.eligible(ts).length} tasks</span></div><span class="tiny muted">Drag to move · Open a card for keyboard-friendly status controls</span></div>${C.board(ts,p)}<p class="tiny muted" style="margin-top:12px">WIP guideline: 4 tasks per lane · Cancelled tasks are available in My Work.</p>`};
P.calendar=()=>{let y=T.ui.calendarYear,m=T.ui.calendarMonth,mode=T.ui.calendarMode,selected=T.ui.calendarDay,scope=T.ui.tabs.calendar||'mine',ts=T.tasks(scope),first=new Date(y,m,1),offset=(first.getDay()+6)%7,start=new Date(y,m,1-offset),days=Array.from({length:42},(_,i)=>{let d=new Date(start);d.setDate(d.getDate()+i);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`});if(mode==='week'){let anchor=selected,off=(new Date(anchor+'T12:00:00').getDay()+6)%7;days=Array.from({length:7},(_,i)=>T.shift(anchor,i-off))}let agenda=ts.filter(t=>t.due===selected);let grid=mode==='day'?`<div style="min-height:400px"><div class="eyebrow">${T.date(selected,{weekday:'long',year:'numeric'})}</div>${agenda.map(t=>`<div class="day-agenda"><span class="tiny muted" style="width:55px">Due today</span><div><button class="task-title" data-action="task-open" data-id="${t.id}">${E(t.title)}</button><p class="tiny muted">${E(T.project(t.project).name)}</p></div><span class="spacer"></span>${C.badge(t.status)}</div>`).join('')||C.empty('Your day has a little space','No task deadlines on this date.',C.btn('Plan a task','task-new','plus','soft',{due:selected}))}</div>`:`<div class="calendar-grid">${['MON','TUE','WED','THU','FRI','SAT','SUN'].map(d=>`<div class="weekday">${d}</div>`).join('')}${days.map(d=>`<div class="cal-cell ${+d.slice(5,7)!==m+1?'other':''} ${d===T.today()?'today':''} ${mode==='week'?'week-cell':''}"><button class="cal-number" aria-label="View ${d}" data-action="calendar-day" data-id="${d}">${+d.slice(-2)}</button>${ts.filter(t=>t.due===d).slice(0,mode==='week'?20:3).map(t=>{let p=T.project(t.project);return `<button class="cal-event" style="--project:${p.color};--project-bg:${p.color}16" data-action="task-open" data-id="${t.id}" title="${E(t.title)}">${E(t.title)}</button>`}).join('')}${mode==='month'&&ts.filter(t=>t.due===d).length>3?`<button class="textbtn" style="font-size:7px" data-action="calendar-day" data-id="${d}">+${ts.filter(t=>t.due===d).length-3} more</button>`:''}</div>`).join('')}</div>`;return C.heading('Your time, thoughtfully planned.','Deadlines, priorities, and a little room to do your best work.',C.btn('Plan a task','task-new','plus','primary',{due:selected}))+`<div class="toolbar"><div class="row">${C.iconbtn('Previous period','calendar-prev','left')}<h2>${mode==='month'?first.toLocaleDateString('en',{month:'long',year:'numeric'}):T.date(selected,{year:'numeric'})}</h2>${C.iconbtn('Next period','calendar-next','right')}${C.btn('Today','calendar-today')}</div><div class="row"><select aria-label="Calendar scope" data-change="calendar-scope"><option value="mine" ${scope==='mine'?'selected':''}>My assigned work</option><option value="company" ${scope==='company'?'selected':''}>Company work</option><option value="personal" ${scope==='personal'?'selected':''}>Private work</option></select><div class="segmented">${['month','week','day'].map(x=>`<button class="${x===mode?'active':''}" data-action="calendar-mode" data-id="${x}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div></div></div><div class="calendar-layout"><section class="card">${grid}</section><div class="stack">${C.card('On '+T.date(selected),agenda.length?agenda.map(t=>`<div class="meeting"><div class="meeting-content"><button class="task-title" style="font-size:11px;white-space:normal" data-action="task-open" data-id="${t.id}">${E(t.title)}</button><p>${E(T.project(t.project).name)}</p></div></div>`).join(''):'<p>No task deadlines for this date.</p>')}${C.card('Your projects',T.projects(scope==='personal'?'personal':scope==='company'?'company':'all').map(p=>`<div class="row" style="padding:9px 0;font-size:10px;color:var(--soft)"><span class="scope-dot" style="--project:${p.color}"></span>${E(p.name)}</div>`).join(''))}</div></div>`};
P.teams=()=>{let tab=T.ui.tabs.teams||'teams',teams=T.db.teams.filter(t=>t.org===T.activeOrg()),ts=T.tasks(),users=T.db.users.filter(u=>teams.some(t=>t.members.includes(u.id)));let body='';if(tab==='teams')body=`<div class="grid3">${teams.map(team=>C.card(`<div class="row"><span class="team-symbol" style="color:${team.color};background:${team.color}16">${I('users')}</span><div>${E(team.name)}<p>${E(team.department)}</p></div></div>`,`<p>Led by ${E(T.user(team.lead).name)} · ${team.members.length} members</p><div class="row between">${C.avatars(team.members)}${C.link('Manage team '+I('arrowUp','sm'),'team-open',{id:team.id})}</div>`,C.iconbtn('Edit team','team-edit','more',{id:team.id}),'team-card')).join('')}</div>`;if(tab==='members')body=`<div class="member-grid">${users.map(u=>C.card('',`${C.avatar(u.id,'lg')}<h3>${E(u.name)}</h3><p>${E(u.title)}</p><p>${E(u.department)} · ${u.capacity}h/week</p><div style="margin-top:13px">${C.badge(u.role,'gray')}</div>`,C.iconbtn('View '+u.name,'member-open','more',{id:u.id}),'member-card')).join('')}</div>`;if(tab==='workload')body=C.card('The next 7 days · estimated effort',`<div class="table-wrap"><table class="capacity-table"><thead><tr><th>Team member</th><th>Assigned tasks</th><th>Planned effort</th><th>Capacity</th><th>Status</th></tr></thead><tbody>${users.map(u=>{let active=ts.filter(t=>t.owner===u.id&&!T.isTerminal(t)&&t.due>=T.today()&&t.due<=T.shift(T.today(),6)),h=active.reduce((a,t)=>a+(+t.hours||0),0),pct=Math.round(h/u.capacity*100);return `<tr class="${pct>100?'overcapacity':''}"><td><div class="row">${C.avatar(u.id)}<div><b>${E(u.name)}</b><p class="tiny muted">${E(u.department)}</p></div></div></td><td>${active.length} tasks</td><td>${h}h / ${u.capacity}h</td><td class="capacity-bar">${C.progress(Math.min(100,pct),pct>100?'var(--orange)':'#a491d4')}<div class="tiny muted" style="margin-top:5px">${pct}% utilization</div></td><td>${C.badge(pct>100?'Over capacity':pct>80?'Well balanced':'Available',pct>100?'orange':pct>80?'blue':'green')}</td></tr>`}).join('')}</tbody></table></div>`,C.btn('Export','export','download'),'','Effort due within the next 7 days ÷ weekly capacity; not a measure of employee value.');return C.heading('Great work starts with great teams.','A little more visibility. A better balance for everyone.',C.btn('Create team','team-new','plus','primary'))+C.tabs([['teams','Team directory',teams.length],['members','People',users.length],['workload','Workload & capacity']],tab,'teams-tab')+body};
P.executive=()=>{let ps=T.projects(),ts=T.tasks(),m=T.metrics(ts),risks=ts.filter(t=>T.overdue(t)||t.status==='Blocked').sort((a,b)=>a.due.localeCompare(b.due));return C.heading('The bigger picture. A clearer direction.','A considered view of portfolio health, delivery, and the decisions that matter.',C.btn('Export snapshot','export','download')+C.btn('Portfolio briefing','ai-brief','sparkles','primary'))+companyNotice()+`<div class="metrics">${C.metric('Active projects',ps.length,`${ps.filter(p=>T.health(p)==='At risk').length} need a closer look`,'folder','',{type:'projects'})}${C.metric('Delivery completion',m.rate+'%',`${m.done} of ${m.total} eligible tasks`,'target','green',{status:'Done'})}${C.metric('Needs attention',m.attention,'Unique overdue + blocked tasks','warning','orange',{status:'attention'})}${C.metric('Open delivery effort',m.hours+'h',m.open+' open company tasks','clock','blue',{status:'open'})}</div><div class="dashboard-grid"><div>${C.card('Portfolio health',`<div class="table-wrap"><table><thead><tr><th>Project</th><th>Owner</th><th>Health</th><th>Completion</th><th>Target</th></tr></thead><tbody>${ps.map(p=>`<tr><td><div class="row">${C.projectIcon(p)}<button class="task-title" style="max-width:240px" data-action="project-open" data-id="${p.id}">${E(p.name)}</button></div></td><td>${C.avatar(p.owner,'sm')}</td><td>${C.badge(T.health(p))}</td><td style="min-width:80px">${C.progress(T.progress(p),p.color)}<p class="tiny muted" style="margin-top:5px">${T.progress(p)}%</p></td><td>${T.date(p.due)}</td></tr>`).join('')}</tbody></table></div>`,C.link('All projects '+I('arrowUp','sm'),'nav',{id:'projects'}))}${C.card('Delivery momentum',C.lineChart(ts),'','','Actual task completions vs task deadlines, ending '+T.date(T.today()))}${C.card('Department focus',`<div class="table-wrap"><table><thead><tr><th>Department</th><th>Open work</th><th>Blocked</th><th>Overdue</th><th>Completion</th></tr></thead><tbody>${[...new Set(ps.map(p=>p.department))].map(d=>{let a=ts.filter(t=>T.project(t.project).department===d),v=T.metrics(a);return `<tr><td>${E(d)}</td><td>${v.open}</td><td>${v.blocked}</td><td>${v.overdue}</td><td>${v.rate}%</td></tr>`}).join('')}</tbody></table></div>`)}</div><div>${C.card('Decisions that need you',risks.length?risks.map(t=>`<div class="risk-row"><span class="metric-icon orange">${I('warning')}</span><div><button class="task-title" style="white-space:normal" data-action="task-open" data-id="${t.id}">${E(t.title)}</button><p>${E(T.project(t.project).name)}</p><div class="row" style="margin-top:10px">${C.badge(t.status)}<span class="tiny muted">${T.user(t.owner).name.split(' ')[0]} · ${T.date(t.due)}</span></div></div></div>`).join(''):C.empty('Clear for the moment','No overdue or blocked company tasks.'))}<section class="card intelligence-card"><div class="card-head"><h2 class="row">${I('sparkles')} Your executive lens</h2></div><p class="intelligence-intro">${m.blocked} blocked tasks and ${m.overdue} overdue tasks. Check the intervention queue before your next portfolio review.</p>${C.btn('Read the portfolio briefing','ai-brief','arrowUp')}<p class="tiny muted" style="margin-top:12px">Rules-based insight · No predictive model</p></section>${C.card('How this view works','<p>Completion is derived from task records. Needs attention is the unique union of blocked and overdue tasks. Personal records are excluded. Project health uses transparent rules, not a predictive score.</p>')}</div></div>`};
P.reports=()=>{let ts=T.tasks().filter(T.inPeriod).filter(t=>T.ui.reportDept==='All departments'||T.project(t.project).department===T.ui.reportDept),m=T.metrics(ts),tab=T.ui.tabs.reports||'overview';let body=tab==='risk'?C.card('Risk register',C.taskTable(ts.filter(t=>T.overdue(t)||t.status==='Blocked'))):tab==='exports'?C.card('Export history',T.db.exports.filter(e=>e.org===T.activeOrg()).map(e=>`<div class="settings-row"><div><h3>${E(e.name)}</h3><p>${T.date(e.date)} · ${e.count} records · ${E(e.scope)}</p></div>${C.badge('Downloaded','green')}</div>`).join('')||C.empty('Ready when you are','Download a CSV to start your export history.')):`<div class="dashboard-grid"><div>${C.card('Delivery, over time',C.lineChart(ts),'','','7-day completions from the filtered task register')}${C.card('Task register',C.taskTable(ts.slice(0,8)),C.badge(ts.length+' records','gray'))}</div><div>${C.card('Status composition',C.donut(ts))}${C.card('Saved views',T.db.savedReports.filter(r=>r.org===T.activeOrg()).map(r=>`<div class="settings-row"><div><h3>${E(r.name)}</h3><p>${E(r.department)} · ${E(r.period)}</p></div>${C.link('Open','report-open',{id:r.id})}</div>`).join('')||'<p>Save this filter combination for your next review.</p>',C.link('+ Save view','report-save'))}</div></div>`;return C.heading('Useful insights. Better conversations.','A shared understanding of progress, with the source records one click away.',C.btn('Save view','report-save','plus')+C.btn('Export CSV','export','download','primary'))+`<div class="toolbar"><div class="filter-group"><select aria-label="Reporting period" data-change="report-period"><option value="all" ${T.ui.reportPeriod==='all'?'selected':''}>All demo records</option><option value="month" ${T.ui.reportPeriod==='month'?'selected':''}>Last 30 days</option><option value="week" ${T.ui.reportPeriod==='week'?'selected':''}>Last 7 days</option></select><select aria-label="Report department" data-change="report-dept">${['All departments',...new Set(T.projects().map(p=>p.department))].map(d=>`<option ${d===T.ui.reportDept?'selected':''}>${E(d)}</option>`).join('')}</select><span class="pill">${E(T.org().name)} · Company only</span></div>${C.link('Metric definitions '+I('info','sm'),'metric-definitions')}</div><div class="metrics">${C.metric('Eligible tasks',m.total,'Cancelled tasks excluded','checkSquare')}${C.metric('Completion',m.rate+'%',m.done+' tasks done','target','green')}${C.metric('Overdue',m.overdue,'Due before the demo reference date','clock','orange')}${C.metric('Needs attention',m.attention,'Unique blocked + overdue records','flag','blue')}</div>${C.tabs([['overview','Delivery overview'],['risk','Risk register'],['exports','Export history',T.db.exports.filter(e=>e.org===T.activeOrg()).length]],tab,'reports-tab')}${body}`};
P.ai=()=>{let blocked=T.tasks().filter(t=>t.status==='Blocked'),all=T.tasks(),m=T.metrics(all),selected=T.ui.aiHistory.at(-1),findings=blocked.map(t=>({id:t.id,title:t.title,desc:t.blockedReason||'A blocked task requires owner review.',task:t.id}));return C.heading('A little intelligence. A lot more clarity.','Context you can trace. Suggestions you can review. Decisions that stay with you.',C.btn('AI policy','ai-policy','shield'))+C.notice('Interactive AI demonstration · Answers are generated from local rules and demo records. No LLM, trained forecast, or autonomous action is connected.','purple','sparkles')+`<div class="ai-layout"><div><section class="card ai-hero"><div class="ai-orb">${I('sparkles','lg')}</div><div class="eyebrow" style="margin-top:20px">YOUR THOUGHT PARTNER, IN CONTEXT</div><h1>See what matters.<br>Make the next move clearer.</h1><p>Explore priorities and dependencies using the current authorized demo workspace.</p><form class="ai-prompt" data-form="ai-ask"><input name="question" placeholder="What needs my attention this week?" aria-label="Ask TaskForce" required><button class="btn primary" type="submit">Ask TaskForce ${I('arrow','sm')}</button></form><div class="suggestions">${['What is blocked?','My highest priorities','Summarize the portfolio'].map(q=>`<button data-action="ai-question" data-question="${q}">${q}</button>`).join('')}</div></section>${selected?`<section class="ai-answer"><div class="row between"><h3>${E(selected.question)}</h3>${C.badge('Rules-based answer','gray')}</div><p style="margin:15px 0">${E(selected.answer)}</p><div class="tiny muted" style="margin-bottom:7px">SOURCE RECORDS · ${selected.scope}</div>${selected.tasks.map(id=>{let t=T.task(id);return t&&T.visibleTask(t)?C.link(I('checkSquare','sm')+' '+E(t.title),'task-open',{id:t.id}):''}).map(html=>`<div style="margin:10px 0">${html}</div>`).join('')||'<p>No matching records.</p>'}<p class="tiny muted" style="margin-top:20px">Method: ${E(selected.method)} · Reference ${T.date(T.today())}</p></section>`:C.card('Your portfolio, in perspective',`<div class="row" style="align-items:flex-start;gap:13px"><span class="metric-icon">${I('sparkles')}</span><div><h3>Keep the next conversation focused.</h3><p style="margin-top:7px">${m.open} open tasks across ${T.projects().length} company projects. ${m.attention} tasks need attention based on blocked status or overdue dates.</p><div style="margin-top:15px">${C.link('Explore the intervention queue '+I('arrowUp','sm'),'nav',{id:'executive'})}</div></div></div>`)}${T.ui.aiHistory.length>1?C.card('Conversation history',T.ui.aiHistory.slice(0,-1).reverse().map((a,i)=>`<div class="settings-row"><p>${E(a.question)}</p>${C.link('Review','ai-history',{id:T.ui.aiHistory.length-i-2})}</div>`).join('')):''}${C.card('Findings worth a closer look',findings.map(f=>`<article class="finding"><div class="row between">${C.badge('Dependency risk','orange')}${T.db.acknowledged.includes(f.id)?C.badge('Acknowledged','green'):C.link('Acknowledge','finding-ack',{id:f.id})}</div><h3>${E(f.title)}</h3><p>${E(f.desc)}</p><div class="row between">${C.link('View source '+I('arrowUp','sm'),'task-open',{id:f.task})}<span class="tiny muted">Source-backed rule · No forecast</span></div></article>`).join('')||C.empty('No blocked-task findings','Your team has no blocked company tasks.'))}</div><div>${C.card('Your data, deliberately routed',`<div class="settings-row"><div><h3>Managed model gateway</h3><p>General, approved context</p></div>${C.badge('Preview','gray')}</div><div class="settings-row"><div><h3>Private model route</h3><p>Confidential enterprise context</p></div>${C.badge('Preview','gray')}</div><p style="margin-top:16px;font-size:10px">Hybrid routing is a policy preview. Production model services must be connected by your engineering team.</p>`)}${C.card('Human review queue',`<div class="approval-empty">${I('shield')}<h3 style="margin:10px 0 7px">You stay in the loop.</h3><p style="font-size:10px">No pending actions. Demo AI never changes tasks, sends email, or reassigns work.</p></div>`)}${C.card('Scope & evidence',`<div class="row">${I('lock','sm')}<h3 style="font-size:11px">${E(T.org().name)}</h3></div><p style="margin-top:12px;font-size:10px">Portfolio answers include only the active organization. “My priorities” may include your own private tasks, labeled in source detail.</p>`)}</div></div>`};
P.people=()=>{let tab=T.ui.peopleTab,hs=T.db.hiring.filter(h=>h.org===T.activeOrg()),cs=T.db.candidates.filter(c=>c.org===T.activeOrg());let body='';if(tab==='hiring')body=`<div class="grid3">${hs.map(h=>C.card(E(h.title),`<p style="font-size:10px">${E(h.department)} · ${h.openings} opening${h.openings>1?'s':''}</p><div class="row between" style="margin-top:25px">${C.avatar(h.manager)}<select data-change="hiring-stage" data-id="${h.id}" aria-label="Hiring stage for ${E(h.title)}" style="font-size:9px">${['Pending approval','Approved','Screening','Interviewing','Offer','Closed'].map(s=>`<option ${h.stage===s?'selected':''}>${s}</option>`).join('')}</select></div>`,C.badge(h.stage))).join('')}${!hs.length?C.card('A fresh hiring pipeline',C.empty('No requests yet','Create your first hiring request.')):''}</div>${C.card('Interview conversations',cs.map(c=>`<div class="settings-row"><div class="row"><span class="avatar" style="--av:#b29bc7">${c.name.split(' ').map(x=>x[0]).join('')}</span><div><h3>${E(c.name)}</h3><p>${E(c.role)} · ${T.date(c.date)} at ${c.time}</p></div></div>${C.btn('View candidate','candidate-open','arrowUp','',{id:c.id})}</div>`).join('')||'<p>No upcoming demo interviews.</p>')}`;if(tab==='onboarding')body=C.card('A confident start',T.db.onboarding.map(o=>`<label class="settings-row"><span><b style="font-size:12px">${E(o.title)}</b><p>New starter checklist · Local demo</p></span><input type="checkbox" data-change="onboarding" data-id="${o.id}" ${o.done?'checked':''}></label>`).join(''));if(tab==='learning')body=`<div class="grid3">${T.db.learning.map(l=>C.card(l.title,`<p>${l.category}</p><div style="margin:22px 0 12px">${C.progress(Math.round(l.completed/l.total*100))}</div><div class="row between"><span class="tiny muted">${l.completed} of ${l.total} lessons</span>${C.btn(l.completed===l.total?'Completed':'Complete next lesson','learning-next','check',l.completed===l.total?'':'soft',{id:l.id})}</div>`)).join('')}</div>`+C.card('Skills matrix',`<div class="skills-grid"><div>Team member</div><div>Leadership</div><div>Technical</div><div>Collaboration</div>${T.db.users.slice(0,5).map((u,i)=>`<div>${E(u.name)}</div>${[4-i%2,2+i%3,3+i%2].map(v=>`<div><span class="skill-level" aria-label="${v} of 4">${[1,2,3,4].map(x=>`<span class="${x<=v?'filled':''}"></span>`).join('')}</span></div>`).join('')}`).join('')}</div><p class="tiny muted" style="margin-top:15px">Illustrative skill levels; these are fictional development records.</p>`);return C.heading('Help good people do great work.','From the next hire to the next skill, make growth intentional.',C.btn('Hiring request','hiring-new','plus','primary'))+C.notice('P1 module demonstration · Fictional hiring and training data. No recruiting service is connected.')+C.tabs([['hiring','Hiring & interviews',hs.length],['onboarding','Onboarding'],['learning','Learning & skills']],tab,'people-tab')+body};
P.mail=()=>{let msgs=T.db.mail.filter(m=>m.org===T.activeOrg()).filter(m=>T.ui.mailFilter!=='Starred'||m.starred);let msg=msgs.find(m=>m.id===T.ui.mailId)||msgs[0];return C.heading('Conversations, connected to progress.','Keep the context. Turn a good conversation into a clear next step.',C.btn('Mailbox settings','mail-connect','mail'))+C.notice('Sample inbox · No Gmail or Microsoft 365 connection. Task conversion uses a review form; no messages are sent.')+`<section class="card mail-layout"><div class="mail-list"><div class="mail-list-header"><div class="row between"><h2>Your inbox</h2>${C.badge(msgs.length+' threads','gray')}</div><select aria-label="Mail view" data-change="mail-filter"><option ${T.ui.mailFilter==='Inbox'?'selected':''}>Inbox</option><option ${T.ui.mailFilter==='Starred'?'selected':''}>Starred</option></select></div>${msgs.map(m=>`<button class="mail-item ${msg?.id===m.id?'selected':''} ${!m.read?'unread':''}" data-action="mail-open" data-id="${m.id}"><div class="row between"><strong>${E(T.user(m.from).name)}</strong><span class="tiny muted">${T.date(m.date)}</span></div><h4>${m.starred?'☆ ':''}${E(m.subject)}</h4><p class="ellipsis">${E(m.body.replace(/\n/g,' ').slice(0,90))}</p></button>`).join('')}</div><div class="mail-content">${msg?`<div class="row between" style="margin-bottom:20px">${C.badge('Sample thread','gray')}<div class="row">${C.iconbtn(msg.starred?'Unstar message':'Star message','mail-star','star',{id:msg.id})}${C.iconbtn('Mark as unread','mail-unread','mail',{id:msg.id})}</div></div><h2>${E(msg.subject)}</h2><div class="row">${C.avatar(msg.from,'lg')}<div><h3>${E(T.user(msg.from).name)}</h3><p class="tiny muted">${E(T.user(msg.from).email)} · To you</p></div><span class="spacer"></span><span class="tiny muted">${T.date(msg.date)}</span></div><div class="mail-body">${E(msg.body)}</div><div class="notice">${I('link','sm')}<span>Suggested project: <b>${E(T.project(msg.project)?.name||'Choose during review')}</b></span></div><div class="mail-toolbar">${C.btn('Review & create task','mail-convert','checkSquare','primary',{id:msg.id})}${C.btn('Save a reply draft','mail-draft','pen','',{id:msg.id})}</div>${msg.draft?`<div class="ai-answer"><div class="tiny muted">LOCAL REPLY DRAFT · NOT SENT</div><p style="margin-top:10px;white-space:pre-line">${E(msg.draft)}</p></div>`:''}`:C.empty('A quieter inbox','No sample messages in this view.')}</div></section>`};
P.automations=()=>{let tab=T.ui.tabs.automations||'rules',rules=T.db.rules.filter(r=>r.org===T.activeOrg());let body=tab==='rules'?`<div class="rules-grid">${rules.map(r=>`<article class="card rule-card"><div class="row between"><span class="metric-icon">${I('zap')}</span>${C.toggle(r.id,r.enabled,r.name,'rule-toggle')}</div><h3>${E(r.name)}</h3><div class="rule-flow"><div class="rule-step"><span>WHEN</span>${E(r.trigger)}</div><div style="text-align:center;color:var(--muted)">↓</div><div class="rule-step"><span>THEN</span>${E(r.action)}</div></div><div class="row between" style="margin-top:20px"><span class="tiny muted">${r.lastRun?'Last run: '+T.date(r.lastRun):'Not run yet'}</span>${C.link('Edit rule','rule-edit',{id:r.id})}</div></article>`).join('')||C.empty('Make room for a smarter routine','Create a rule to get started.')}</div>`:tab==='alerts'?C.card('Alert inbox',C.notifications(T.db.notifications.filter(n=>n.org===T.activeOrg()))):C.card('Local run history',T.db.runs.filter(r=>r.org===T.activeOrg()).map(r=>`<div class="settings-row"><div><h3>${E(r.name)}</h3><p>${T.date(r.date)} · ${r.matches} matching tasks</p></div>${C.badge('Simulated','blue')}</div>`).join('')||C.empty('No rules evaluated yet','Run a local simulation to inspect matching task records.'));return C.heading('Little routines. Meaningful momentum.','Bring the right signal to the right person, at the right moment.',C.btn('Run simulation','rules-run','play')+C.btn('Create rule','rule-new','plus','primary'))+C.notice('Rules run only when you click “Run simulation”. No scheduler, background job, email, or external notification is connected.')+C.tabs([['rules','Workflow rules',rules.length],['alerts','Alert inbox',T.db.notifications.filter(n=>n.org===T.activeOrg()&&!n.read).length],['runs','Run history']],tab,'automations-tab')+body};
C.notifications=ns=>ns.length?ns.map(n=>`<div class="notification-item ${!n.read?'unread':''}"><span class="metric-icon ${n.read?'blue':'orange'}">${I(n.read?'check':'bell')}</span><div style="flex:1"><button class="task-title" data-action="notification-open" data-id="${n.id}">${E(n.title)}</button><p>${E(n.detail)} · ${T.date(n.date)}</p></div>${!n.read?C.iconbtn('Mark read','notification-read','check',{id:n.id}):''}</div>`).join(''):C.empty('All clear for now','New local alerts will appear here.');
const providers=[['microsoft','Microsoft 365','Mail, calendar & collaboration','M','#7090c4','#eef3fb'],['google','Google Workspace','Gmail, calendar & shared context','G','#bc8d72','#fbf3ec'],['slack','Slack','Team updates where conversations happen','#','#a78cba','#f7f0fb'],['jira','Jira','Engineering issues & sprint context','J','#7199c9','#edf3fb'],['github','GitHub','Pull requests, commits & release activity','⌘','#7b7f94','#f0f1f7'],['webhooks','Custom webhooks','Workspace events for your own systems','↗','#83a593','#eff6f2']];
P.integrations=()=>{let tab=T.ui.integrationTab;let body=tab==='catalog'?`<div class="grid3">${providers.map(([id,name,desc,mark,color,bg])=>{let connected=T.db.integrations.some(c=>c.org===T.activeOrg()&&c.provider===id);return `<article class="card integration-card"><div class="row between"><span class="integration-logo" style="--provider:${color};--provider-bg:${bg}">${mark}</span>${C.badge(connected?'Connected · demo':'Not connected',connected?'green':'gray')}</div><h3 style="margin-top:20px">${name}</h3><p>${desc}</p>${C.btn(connected?'Manage connection':'Configure demo','integration-open','arrowUp','',{id})}</article>`}).join('')}</div>`:tab==='clients'?C.card('Scoped API clients',T.db.clients.filter(c=>c.org===T.activeOrg()).map(c=>`<div class="settings-row"><div><h3>${E(c.name)}</h3><p>${E(c.scope)} · Preview identifier ${E(c.id)}</p></div>${C.btn('Revoke','client-revoke','trash','danger',{id:c.id})}</div>`).join('')||C.empty('A deliberate connection starts here','Create a scoped demo client. No live credentials are issued.'),C.btn('New client','client-new','plus','soft')):tab==='webhooks'?C.card('Webhook endpoints',T.db.webhooks.filter(h=>h.org===T.activeOrg()).map(h=>`<div class="settings-row"><div><h3>${E(h.name)}</h3><p>${E(h.url)} · ${E(h.event)}</p></div><div class="row">${C.btn('Test locally','webhook-test','play','',{id:h.id})}${C.iconbtn('Remove webhook','webhook-remove','trash',{id:h.id})}</div></div>`).join('')||C.empty('Keep downstream systems informed','Add a sample endpoint to simulate an event delivery.'),C.btn('Add webhook','webhook-new','plus','soft')):C.card('Simulation logs',T.db.webhookLogs.filter(l=>l.org===T.activeOrg()).map(l=>`<div class="settings-row"><div><h3>${E(l.name)}</h3><p>${E(l.event)} · ${T.date(l.date)}</p></div>${C.badge('Local test only','blue')}</div>`).join('')||C.empty('No deliveries to inspect','Test a webhook to generate a local log entry.'));return C.heading('A connected workspace, by design.','Thoughtful integrations for the tools your people already use.',C.btn('Developer guide','api-docs','code'))+C.notice('Integration UI demo · Connections are simulated, credentials are not generated, and no network calls are made.')+C.tabs([['catalog','App catalog'],['clients','API clients'],['webhooks','Webhooks'],['logs','Delivery logs']],tab,'integrations-tab')+body};
P.settings=()=>{let tab=T.ui.settingsTab,p=T.db.preferences,org=T.org();const tabs=[['profile','users','My profile'],['organization','briefcase','Organization'],['members','users','Members & roles'],['security','shield','Security & access'],['ai','sparkles','AI governance'],['audit','list','Audit log'],['billing','pie','Plan & usage'],['preferences','settings','Preferences & data']];let body='';if(tab==='profile')body=C.card('The person behind the work',`<div class="row" style="margin-bottom:25px">${C.avatar('u1','lg')}<div><h3>${E(T.me().name)}</h3><p class="tiny muted">Your personal workspace remains yours.</p></div></div><form data-form="profile"><div class="form-grid">${C.field('Full name','name','text',T.me().name,null,false,'required maxlength="80"')}${C.field('Job title','title','text',T.me().title,null,false,'required maxlength="80"')}${C.field('Demo email address','email','email',T.me().email,null,false,'required')}${C.field('Timezone','timezone','text',p.timezone,['Asia/Kolkata','UTC','Europe/London','America/New_York'])}</div><div class="modal-actions"><button class="btn primary" type="submit">Save profile</button></div></form>`);if(tab==='organization')body=C.card('A shared home for your team',`<form data-form="organization"><div class="form-grid">${C.field('Organization name','name','text',org.name,null,true,'required maxlength="80"')}${C.field('Industry','industry','text',org.industry,null,false,'required')}${C.field('Data region · policy preview','region','text',org.region,['India','EU','US'])}</div><div class="modal-actions"><button class="btn primary">Save organization</button></div></form><div class="settings-row"><div><h3>Workspace isolation</h3><p>Context switching filters all company views. Backend enforcement is required for production.</p></div>${C.badge('Demo scope','gray')}</div>`);if(tab==='members')body=C.card('People & permissions',C.notice('Role simulation changes navigation and editing controls. It is not a server-side security boundary.')+`<div class="table-wrap"><table><thead><tr><th>Member</th><th>Role</th><th>Status</th></tr></thead><tbody>${T.db.users.map(u=>`<tr><td><div class="row">${C.avatar(u.id)}<div><b>${E(u.name)}</b><p class="tiny muted">${E(u.email)}</p></div></div></td><td>${u.id==='u1'?E(T.db.session.role):`<select aria-label="Role for ${E(u.name)}" data-change="member-role" data-id="${u.id}" style="font-size:9px">${T.ROLES.map(r=>`<option ${r===u.role?'selected':''}>${r}</option>`).join('')}</select>`}</td><td>${C.badge(u.status)}</td></tr>`).join('')}${T.db.invites.filter(i=>i.org===T.activeOrg()).map(i=>`<tr><td>${E(i.email)}</td><td>${E(i.role)}</td><td>${C.badge('Invited · local','orange')}</td></tr>`).join('')}</tbody></table></div><div style="margin-top:20px">${C.link('View role permission matrix '+I('arrowUp','sm'),'role-matrix')}</div>`,C.btn('Invite member','member-invite','plus','soft'));if(tab==='security')body=C.card('Deliberate access controls',C.notice('Security settings below are configuration previews; no IdP, MFA enforcement, or session service is connected.')+`<div class="settings-row"><div><h3>Enterprise single sign-on</h3><p>OIDC / SAML federation</p></div>${C.btn('Configure preview','sso-config','shield')}</div><div class="settings-row"><div><h3>Multi-factor authentication</h3><p>Managed by enterprise identity provider in production</p></div>${C.badge('Not connected','gray')}</div><div class="settings-row"><div><h3>Role preview</h3><p>Use the profile menu to explore a different role.</p></div>${C.btn('Switch role','profile-menu','users')}</div><div class="settings-row"><div><h3>HR scope for owner demo</h3><p>Separate explicit grant for hiring data previews</p></div>${C.toggle('hrScope',p.hrScope,'HR scope')}</div><div class="settings-row"><div><h3>Retention policy</h3><p>Proposed audit retention · Not enforced locally</p></div>${C.badge('365 days · preview','gray')}</div>`);if(tab==='ai')body=C.card('Hybrid AI governance',C.notice('AI policy controls are saved locally. Model routing and enforcement need production services.')+[['aiPrivate','Confidential context → private model','Route sensitive workloads through a tenant-approved private model.'],['aiReview','Human review before action','Require a person to review any future AI write operation.']].map(([key,name,desc])=>`<div class="settings-row"><div><h3>${name}</h3><p>${desc}</p></div>${C.toggle(key,p[key],name)}</div>`).join('')+`<div class="settings-row"><div><h3>Foundation model training</h3><p>Not part of the blueprint or this demo</p></div>${C.badge('Disabled','gray')}</div>`);if(tab==='audit')body=C.card('An understandable change history',C.activity(T.db.activity.filter(a=>a.org===T.activeOrg())),C.btn('Export audit','audit-export','download'),'','Local demonstration log · Not tamper-resistant');if(tab==='billing')body=C.card('Room for your whole organization',`<div class="row between"><div><div class="eyebrow">YOUR PLAN</div><h1>Enterprise</h1><p>Demo subscription · No charges or payment service.</p></div>${C.badge('Demo workspace','gray')}</div><div class="metrics" style="grid-template-columns:repeat(3,1fr);margin:28px 0 10px">${C.metric('Demo members',T.db.users.length,'Fictional directory','users')}${C.metric('Active projects',T.projects().length,'Company portfolio','folder')}${C.metric('Stored tasks',T.tasks().length,'Company records','checkSquare')}</div>`);if(tab==='preferences')body=C.card('Make this space feel like yours',`<div class="settings-row"><div><h3>Appearance</h3><p>Switch between light and dark themes.</p></div><div class="segmented">${['light','dark'].map(s=>`<button data-action="theme" data-id="${s}" class="${p.theme===s?'active':''}">${I(s==='light'?'sun':'moon')} ${s}</button>`).join('')}</div></div><div class="settings-row"><div><h3>Information density</h3><p>A little more breathing room, or a little more detail.</p></div><select data-change="density" aria-label="Information density"><option value="comfortable" ${p.density==='comfortable'?'selected':''}>Comfortable</option><option value="compact" ${p.density==='compact'?'selected':''}>Compact</option></select></div><div class="settings-row"><div><h3>Demo reference date</h3><p>Due-today and overdue metrics use this date for reproducible demos.</p></div><input type="date" aria-label="Demo reference date" value="${T.today()}" data-change="reference-date" required></div><div class="settings-row"><div><h3>Weekly digest preference</h3><p>Local preference only; no emails are sent.</p></div>${C.toggle('digest',p.digest,'Weekly digest')}</div><div class="settings-row"><div><h3>Export your demo workspace</h3><p>JSON backup of all local workspaces, including your private demo data.</p></div>${C.btn('Download backup','backup','download')}</div><div class="settings-row"><div><h3>Restore a demo backup</h3><p>Validates and replaces local records after confirmation.</p></div>${C.btn('Import JSON','import','upload')}</div><div class="settings-row"><div><h3>Start fresh</h3><p>Reset all browser demo changes to the sample data.</p></div>${C.btn('Reset demo','reset-confirm','refresh','danger')}</div>`);return C.heading('A workspace that works your way.','Considered controls for your people, your work, and your data.')+`<div class="settings-layout"><nav class="settings-nav" aria-label="Settings sections">${tabs.map(([id,icon,title])=>`<button class="${id===tab?'active':''}" data-action="settings-tab" data-id="${id}">${I(icon)}${title}</button>`).join('')}</nav><div>${body}</div></div>`};
P.denied=()=>C.heading('A little outside your current scope.','This module needs a different role in the blueprint.')+C.card('Role preview',C.empty('This view needs a different permission',`Your current demo role is ${T.db.session.role}. Switch roles to explore all modules.`,C.btn('Choose a demo role','profile-menu','users','primary'))+C.notice('Frontend role previews illustrate intended permissions. They do not replace backend authorization.'));
P.notfound=()=>C.heading('Let’s get you back to your workspace.','This route could not be found.')+C.empty('A missing page','Choose a module from the sidebar.',C.btn('Go to dashboard','nav','dashboard','primary',{id:'dashboard'}));
})();
